def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    out = np.zeros((3, 3), dtype=int)
    emit(out, "Allocate an empty 3x3 canvas for the hole counts.")
    # enclosed background regions
    counts = {}
    minx = {}
    for comp in components(g == 0):
        if any(y in (0, H - 1) or x in (0, W - 1) for y, x in comp):
            continue
        col = None
        for y, x in comp:
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                yy, xx = y + dy, x + dx
                if 0 <= yy < H and 0 <= xx < W and g[yy, xx] != 0:
                    col = int(g[yy, xx]); break
            if col is not None:
                break
        if col is None:
            continue
        counts[col] = counts.get(col, 0) + len(comp)
    for c in counts:
        minx[c] = min(x for y, x in zip(*np.where(g == c)))
    row = 0
    for c in sorted(counts, key=lambda c: minx[c]):
        n = counts[c]
        pos = row * 3
        for i in range(n):
            if pos + i < 9:
                out[(pos + i) // 3, (pos + i) % 3] = c
        row += (n + 2) // 3
        emit(out, f"Shape colour {c} encloses {n} cells: write {n} cells of colour {c} starting on a new row.")
    emit(out, "Final canvas.")
    return out
